syntax = "proto3";

package kit.sandbox.v1;

import "buf/validate/validate.proto";
import "google/protobuf/duration.proto";
import "kit/codegen/v1/options.proto";
import "kit/sandbox/v1/sandbox.proto";

option go_package = "github.com/sandbox-kit/kit/sdks/go/sandbox;sandbox";
option (kit.codegen.v1.client) = {
  creation_service: "SandboxService"
  config_message: "Config"
};

// is the shared client configuration. Provider is attached by the generator and is not serialized.
//
// Example:
//
//	client, err := NewClient(Config{
//	    Provider: provider,
//	    Timeout:  Value(2 * time.Minute),
//	})
message Config {
  // is one credential alternative. Nil lets the native SDK resolve its own environment or profile.
  AuthConfig auth = 1;
  // is the provider API URL where the integration supports an override.
  // HTTPS is required except for loopback HTTP; that secure_endpoint check stays handwritten.
  optional string endpoint = 2 [(buf.validate.field).cel = {
    id: "nonblank"
    message: "must not be blank"
    expression: "this.trim() != ''"
  }];
  // is a region or target preference.
  optional string region = 3 [(buf.validate.field).cel = {
    id: "nonblank"
    message: "must not be blank"
    expression: "this.trim() != ''"
  }];
  // is the app, environment, organization, or project scope. JSON name is "context".
  Scope scope = 4 [json_name = "context"];
  // is the default Kit operation deadline. An explicit creation timeout overrides it.
  // Nil and explicit zero add no Kit deadline.
