package sandbox

// APIKeyAuth builds AuthConfig for an API-key credential.
func APIKeyAuth(key string) *AuthConfig {
	return &AuthConfig{Credentials: &AuthConfig_ApiKey{ApiKey: &APIKeyCredentials{Key: key}}}
}

// TokenPairAuth builds AuthConfig for a token-id / token-secret pair.
func TokenPairAuth(id, secret string) *AuthConfig {
	return &AuthConfig{Credentials: &AuthConfig_TokenPair{TokenPair: &TokenPairCredentials{Id: id, Secret: secret}}}
}

// BearerTokenAuth builds AuthConfig for a bearer or JWT credential.
func BearerTokenAuth(token string) *AuthConfig {
	return &AuthConfig{Credentials: &AuthConfig_BearerToken{BearerToken: &BearerTokenCredentials{Token: token}}}
}

// OAuthClientSecretAuth builds AuthConfig for OAuth refresh with a client secret.
func OAuthClientSecretAuth(refreshToken, clientID, clientSecret string) *AuthConfig {
	return &AuthConfig{Credentials: &AuthConfig_OauthRefresh{OauthRefresh: &OAuthCredentials{
		RefreshToken: refreshToken,
		ClientId:     clientID,
		ClientSecret: Value(clientSecret),
	}}}
}

// OAuthJWTAuth builds AuthConfig for OAuth refresh with a JWT signing key.
func OAuthJWTAuth(refreshToken, clientID, jwtKey string) *AuthConfig {
	return &AuthConfig{Credentials: &AuthConfig_OauthRefresh{OauthRefresh: &OAuthCredentials{
		RefreshToken: refreshToken,
		ClientId:     clientID,
		JwtKey:       Value(jwtKey),
	}}}
}

// FromImage builds a sandbox source from a container image reference.
func FromImage(reference string) *SandboxSource {
	return &SandboxSource{Kind: &SandboxSource_Image{Image: &ImageSource{Reference: reference}}}
}

// FromSnapshot builds a sandbox source from an existing snapshot reference.
func FromSnapshot(reference string) *SandboxSource {
	return &SandboxSource{Kind: &SandboxSource_Snapshot{Snapshot: &SnapshotSource{Reference: reference}}}
}

// FromWarmPool builds a sandbox source from a warm-pool reference.
func FromWarmPool(reference string) *SandboxSource {
	return &SandboxSource{Kind: &SandboxSource_WarmPool{WarmPool: &WarmPoolSource{Reference: reference}}}
}

// ProviderDefault builds a sandbox source that asks the provider to choose its default.
func ProviderDefault() *SandboxSource {
	return &SandboxSource{Kind: &SandboxSource_ProviderDefault{ProviderDefault: &ProviderDefaultSource{}}}
}

package sandbox_test

import (
	"testing"

	"github.com/sandbox-kit/kit/sdks/go/sandbox"
