func TestAuthConstructors(t *testing.T) {
	if got := sandbox.APIKeyAuth("k").GetApiKey().GetKey(); got != "k" {
		t.Fatalf("APIKeyAuth: %q", got)
	}
	pair := sandbox.TokenPairAuth("id", "secret")
	if pair.GetTokenPair().GetId() != "id" || pair.GetTokenPair().GetSecret() != "secret" {
		t.Fatalf("TokenPairAuth: %#v", pair.GetTokenPair())
	}
	if got := sandbox.BearerTokenAuth("tok").GetBearerToken().GetToken(); got != "tok" {
		t.Fatalf("BearerTokenAuth: %q", got)
	}
	oauth := sandbox.OAuthClientSecretAuth("refresh", "client", "secret")
	if oauth.GetOauthRefresh().GetClientSecret() == nil || *oauth.GetOauthRefresh().GetClientSecret() != "secret" {
		t.Fatalf("OAuthClientSecretAuth: %#v", oauth.GetOauthRefresh())
	}
	jwt := sandbox.OAuthJWTAuth("refresh", "client", "key")
	if jwt.GetOauthRefresh().GetJwtKey() == nil || *jwt.GetOauthRefresh().GetJwtKey() != "key" {
		t.Fatalf("OAuthJWTAuth: %#v", jwt.GetOauthRefresh())
	}
}

