package sandbox

import (
	sandboxv1 "github.com/sandbox-kit/kit/sdks/go/contracts/kit/sandbox/v1"

	"google.golang.org/protobuf/types/known/durationpb"
)

// Config is the public client configuration. Auth uses exclusive fields instead
// of protobuf oneof wrappers; NewClient converts to the wire message before
// Protovalidate and provider initialization.
type Config struct {
	Auth     *AuthConfig
	Endpoint *string
	Region   *string
	Scope    *Scope
	Timeout  *durationpb.Duration
}

// AuthConfig holds exactly one credential alternative for public construction.
type AuthConfig struct {
	APIKey       *APIKeyCredentials
	TokenPair    *TokenPairCredentials
	BearerToken  *BearerTokenCredentials
	OAuthRefresh *OAuthCredentials
}

// CreateOptions is the public create request. Source uses exclusive fields
// instead of protobuf oneof wrappers.
type CreateOptions struct {
	Name            *string
	Source          *SandboxSource
	Runtime         *RuntimeConfig
	Isolation       *IsolationConfig
	Resources       *Resources
	Placement       *Placement
	Environment     map[string]string
	Labels          map[string]string
	Network         *NetworkConfig
	Security        *SecurityConfig
	Lifetime         *LifetimePolicy
	Provisioning    *ProvisioningOptions
	Readiness       *ReadinessProbe
	Observability   *ObservabilityConfig
	ProviderOptions *MetadataObject
}

// SandboxSource holds exactly one source alternative for public construction.
type SandboxSource struct {
	ProviderDefault *ProviderDefaultSource
	Image           *ImageSource
	Snapshot        *SnapshotSource
	WarmPool        *WarmPoolSource
}

func toProtoConfig(config *Config) *sandboxv1.Config {
	if config == nil {
		return nil
	}
	out := &sandboxv1.Config{
		Endpoint: config.Endpoint,
		Region:   config.Region,
		Scope:    config.Scope,
		Timeout:  config.Timeout,
	}
	if config.Auth != nil {
		out.Auth = toProtoAuth(config.Auth)
	}
	return out
}

func toProtoAuth(auth *AuthConfig) *sandboxv1.AuthConfig {
	if auth == nil {
		return nil
	}
	out := &sandboxv1.AuthConfig{}
	switch {
	case auth.APIKey != nil:
		out.Credentials = &sandboxv1.AuthConfig_ApiKey{ApiKey: auth.APIKey}
	case auth.TokenPair != nil:
		out.Credentials = &sandboxv1.AuthConfig_TokenPair{TokenPair: auth.TokenPair}
	case auth.BearerToken != nil:
		out.Credentials = &sandboxv1.AuthConfig_BearerToken{BearerToken: auth.BearerToken}
	case auth.OAuthRefresh != nil:
		out.Credentials = &sandboxv1.AuthConfig_OauthRefresh{OauthRefresh: auth.OAuthRefresh}
	}
	return out
}

func toProtoCreateOptions(request *CreateOptions) *sandboxv1.CreateOptions {
	if request == nil {
		return nil
	}
	out := &sandboxv1.CreateOptions{
		Name:            request.Name,
		Runtime:         request.Runtime,
		Isolation:       request.Isolation,
		Resources:       request.Resources,
		Placement:       request.Placement,
		Environment:     request.Environment,
		Labels:          request.Labels,
		Network:         request.Network,
		Security:        request.Security,
		Lifetime:         request.Lifetime,
		Provisioning:    request.Provisioning,
		Readiness:       request.Readiness,
		Observability:   request.Observability,
		ProviderOptions: request.ProviderOptions,
	}
	if request.Source != nil {
		out.Source = toProtoSource(request.Source)
	}
	return out
}

func toProtoSource(source *SandboxSource) *sandboxv1.SandboxSource {
	if source == nil {
		return nil
	}
	out := &sandboxv1.SandboxSource{}
	switch {
	case source.ProviderDefault != nil:
		out.Kind = &sandboxv1.SandboxSource_ProviderDefault{ProviderDefault: source.ProviderDefault}
	case source.Image != nil:
		out.Kind = &sandboxv1.SandboxSource_Image{Image: source.Image}
	case source.Snapshot != nil:
		out.Kind = &sandboxv1.SandboxSource_Snapshot{Snapshot: source.Snapshot}
	case source.WarmPool != nil:
		out.Kind = &sandboxv1.SandboxSource_WarmPool{WarmPool: source.WarmPool}
	}
	return out
}

