package sandbox

import (
	sandboxv1 "github.com/sandbox-kit/kit/sdks/go/contracts/kit/sandbox/v1"

	"google.golang.org/protobuf/types/known/durationpb"
)

// Config is the public client configuration. Nested types are plain structs;
// NewClient converts to protobuf before Protovalidate and provider calls.
type Config struct {
	Auth     *AuthConfig
	Endpoint *string
	Region   *string
	Scope    *Scope
	Timeout  *durationpb.Duration
}

// AuthConfig holds exactly one credential alternative.
type AuthConfig struct {
	APIKey       *APIKeyCredentials
	TokenPair    *TokenPairCredentials
	BearerToken  *BearerTokenCredentials
	OAuthRefresh *OAuthCredentials
}

// APIKeyCredentials is an API-key credential.
type APIKeyCredentials struct {
	Key string
}

// TokenPairCredentials is a token-id / token-secret pair.
type TokenPairCredentials struct {
	Id     string
	Secret string
}

// BearerTokenCredentials is a bearer or JWT credential.
type BearerTokenCredentials struct {
	Token string
}

// OAuthCredentials is an OAuth refresh credential. Supply exactly one of
// ClientSecret or JwtKey.
type OAuthCredentials struct {
	RefreshToken string
	ClientId     string
	ClientSecret *string
	JwtKey       *string
}

// Scope is app, environment, organization, or project scope.
type Scope struct {
	AppName        *string
	Environment    *string
	OrganizationId *string
	ProjectId      *string
}

// CreateOptions is the public create request.
type CreateOptions struct {
	Name            *string
	Source          *SandboxSource
	Runtime         *RuntimeConfig
	Isolation       *IsolationConfig
	Resources       *Resources
	Placement       *Placement
	Environment     map[string]string
	Labels          map[string]string
	Network         *NetworkConfig
	Security        *SecurityConfig
	Lifetime         *LifetimePolicy
	Provisioning    *ProvisioningOptions
	Readiness       *ReadinessProbe
	Observability   *ObservabilityConfig
	ProviderOptions *MetadataObject
}

// SandboxSource holds exactly one source alternative.
type SandboxSource struct {
	ProviderDefault *ProviderDefaultSource
	Image           *ImageSource
	Snapshot        *SnapshotSource
	WarmPool        *WarmPoolSource
}

// ProviderDefaultSource asks the provider to choose its default source.
type ProviderDefaultSource struct{}

// ImageSource is a container image reference.
type ImageSource struct {
	Reference string
}

// SnapshotSource is an existing snapshot.
type SnapshotSource struct {
	Reference    string
	Kind         SnapshotKind
	ProviderKind *string
}

// WarmPoolSource is an existing warm pool.
type WarmPoolSource struct {
	Reference string
}

// RuntimeConfig is process setup applied when the sandbox starts.
type RuntimeConfig struct {
	Language         *string
	Version          *string
	User             *string
	WorkingDirectory *string
	Entrypoint       []string
	Pty              *bool
}

// IsolationConfig selects how the sandbox is isolated.
type IsolationConfig struct {
	Kind                 IsolationKind
	ProviderKind         *string
	NestedVirtualization *bool
}

// Resources is the requested compute size.
type Resources struct {
	CpuCores       *float64
	CpuLimitCores  *float64
	MemoryMib      *uint64
	MemoryLimitMib *uint64
	DiskMib        *uint64
}

// Placement is a placement preference.
type Placement struct {
	Cloud   *string
	Regions []string
	Target  *string
}

// StringAllowlist is an allowlist. A present empty list means deny all.
type StringAllowlist struct {
	Entries []string
}

// NetworkConfig is creation-time networking.
type NetworkConfig struct {
	Egress           EgressMode
	OutboundCidrs    *StringAllowlist
	OutboundDomains  *StringAllowlist
	InboundCidrs     *StringAllowlist
	PrivateNetwork   *bool
	LinkedSandbox    *string
	ProxyReference   *string
	OutboundProxyUrl *string
	CustomDomain     *string
	Ports            []*PortBinding
}

// PortBinding publishes one port.
type PortBinding struct {
	Port      uint32
	Transport PortTransport
}

// SecurityConfig sets access and secret references.
type SecurityConfig struct {
	PublicAccess     *bool
	WorkloadIdentity *bool
	Secrets          []*SecretReference
}

// SecretReference names a provider-managed secret.
type SecretReference struct {
	Reference           string
	EnvironmentVariable *string
	Injection           SecretInjection
}

// LifetimePolicy is requested at creation.
type LifetimePolicy struct {
	MaximumLifetime *durationpb.Duration
	Ephemeral       *bool
	IdleTerminate   *AutomaticAction
	IdleStop        *AutomaticAction
	IdlePause       *AutomaticAction
	StoppedArchive  *AutomaticAction
	StoppedDelete   *AutomaticAction
}

// AutomaticAction is one idle or stopped policy.
type AutomaticAction struct {
	Mode  PolicyMode
	After *durationpb.Duration
}

// ProvisioningOptions is creation waiting, separate from sandbox lifetime.
type ProvisioningOptions struct {
	Timeout      *durationpb.Duration
	QueueTimeout *durationpb.Duration
	WaitFor      WaitCondition
}

// ReadinessProbe is the check used when waiting until ready. Set TcpPort or Command.
type ReadinessProbe struct {
	TcpPort *uint32
	Command *CommandProbe
}

// CommandProbe is a command readiness check.
type CommandProbe struct {
	Argv []string
}

// ObservabilityConfig sets provider logging and telemetry options.
type ObservabilityConfig struct {
	Verbose           *bool
	TelemetryEndpoint *string
}

// ToProtoConfig converts public client configuration into the wire message.
func ToProtoConfig(config *Config) *sandboxv1.Config {
	return toProtoConfig(config)
}

// ToProtoCreateOptions converts a public create request into the wire message.
func ToProtoCreateOptions(request *CreateOptions) *sandboxv1.CreateOptions {
	return toProtoCreateOptions(request)
}

package sandbox

import sandboxv1 "github.com/sandbox-kit/kit/sdks/go/contracts/kit/sandbox/v1"

func toProtoConfig(config *Config) *sandboxv1.Config {
	if config == nil {
		return nil
	}
	return &sandboxv1.Config{
		Auth:     toProtoAuth(config.Auth),
		Endpoint: config.Endpoint,
		Region:   config.Region,
		Scope:    toProtoScope(config.Scope),
		Timeout:  config.Timeout,
	}
}

func toProtoAuth(auth *AuthConfig) *sandboxv1.AuthConfig {
	if auth == nil {
		return nil
	}
	out := &sandboxv1.AuthConfig{}
	switch {
	case auth.APIKey != nil:
		out.Credentials = &sandboxv1.AuthConfig_ApiKey{ApiKey: toProtoAPIKey(auth.APIKey)}
	case auth.TokenPair != nil:
		out.Credentials = &sandboxv1.AuthConfig_TokenPair{TokenPair: toProtoTokenPair(auth.TokenPair)}
	case auth.BearerToken != nil:
		out.Credentials = &sandboxv1.AuthConfig_BearerToken{BearerToken: toProtoBearer(auth.BearerToken)}
	case auth.OAuthRefresh != nil:
		out.Credentials = &sandboxv1.AuthConfig_OauthRefresh{OauthRefresh: toProtoOAuth(auth.OAuthRefresh)}
	}
	return out
}

func toProtoAPIKey(v *APIKeyCredentials) *sandboxv1.APIKeyCredentials {
	if v == nil {
		return nil
	}
	return &sandboxv1.APIKeyCredentials{Key: v.Key}
}

func toProtoTokenPair(v *TokenPairCredentials) *sandboxv1.TokenPairCredentials {
	if v == nil {
		return nil
	}
	return &sandboxv1.TokenPairCredentials{Id: v.Id, Secret: v.Secret}
}

func toProtoBearer(v *BearerTokenCredentials) *sandboxv1.BearerTokenCredentials {
	if v == nil {
		return nil
	}
	return &sandboxv1.BearerTokenCredentials{Token: v.Token}
}

func toProtoOAuth(v *OAuthCredentials) *sandboxv1.OAuthCredentials {
	if v == nil {
		return nil
	}
	return &sandboxv1.OAuthCredentials{
		RefreshToken: v.RefreshToken,
		ClientId:     v.ClientId,
		ClientSecret: v.ClientSecret,
		JwtKey:       v.JwtKey,
	}
}

func toProtoScope(v *Scope) *sandboxv1.Scope {
	if v == nil {
		return nil
	}
	return &sandboxv1.Scope{
		AppName:        v.AppName,
		Environment:    v.Environment,
		OrganizationId: v.OrganizationId,
		ProjectId:      v.ProjectId,
	}
}

func toProtoCreateOptions(request *CreateOptions) *sandboxv1.CreateOptions {
	if request == nil {
		return nil
	}
	return &sandboxv1.CreateOptions{
		Name:            request.Name,
		Source:          toProtoSource(request.Source),
		Runtime:         toProtoRuntime(request.Runtime),
		Isolation:       toProtoIsolation(request.Isolation),
		Resources:       toProtoResources(request.Resources),
		Placement:       toProtoPlacement(request.Placement),
		Environment:     request.Environment,
		Labels:          request.Labels,
		Network:         toProtoNetwork(request.Network),
		Security:        toProtoSecurity(request.Security),
		Lifetime:         toProtoLifetime(request.Lifetime),
		Provisioning:    toProtoProvisioning(request.Provisioning),
		Readiness:       toProtoReadiness(request.Readiness),
		Observability:   toProtoObservability(request.Observability),
		ProviderOptions: request.ProviderOptions,
	}
}

func toProtoSource(source *SandboxSource) *sandboxv1.SandboxSource {
	if source == nil {
		return nil
	}
	out := &sandboxv1.SandboxSource{}
	switch {
	case source.ProviderDefault != nil:
		out.Kind = &sandboxv1.SandboxSource_ProviderDefault{ProviderDefault: &sandboxv1.ProviderDefaultSource{}}
	case source.Image != nil:
		out.Kind = &sandboxv1.SandboxSource_Image{Image: toProtoImage(source.Image)}
	case source.Snapshot != nil:
		out.Kind = &sandboxv1.SandboxSource_Snapshot{Snapshot: toProtoSnapshot(source.Snapshot)}
	case source.WarmPool != nil:
		out.Kind = &sandboxv1.SandboxSource_WarmPool{WarmPool: toProtoWarmPool(source.WarmPool)}
	}
	return out
}

func toProtoImage(v *ImageSource) *sandboxv1.ImageSource {
	if v == nil {
		return nil
	}
	return &sandboxv1.ImageSource{Reference: v.Reference}
}

func toProtoSnapshot(v *SnapshotSource) *sandboxv1.SnapshotSource {
	if v == nil {
		return nil
	}
	return &sandboxv1.SnapshotSource{
		Reference:    v.Reference,
		Kind:         v.Kind,
		ProviderKind: v.ProviderKind,
	}
}

func toProtoWarmPool(v *WarmPoolSource) *sandboxv1.WarmPoolSource {
	if v == nil {
		return nil
	}
	return &sandboxv1.WarmPoolSource{Reference: v.Reference}
}

func toProtoRuntime(v *RuntimeConfig) *sandboxv1.RuntimeConfig {
	if v == nil {
		return nil
	}
	return &sandboxv1.RuntimeConfig{
		Language:         v.Language,
		Version:          v.Version,
		User:             v.User,
		WorkingDirectory: v.WorkingDirectory,
		Entrypoint:       v.Entrypoint,
		Pty:              v.Pty,
	}
}

func toProtoIsolation(v *IsolationConfig) *sandboxv1.IsolationConfig {
	if v == nil {
		return nil
	}
	return &sandboxv1.IsolationConfig{
