// Command protoc-gen-kit-public emits idiomatic public request/config façades
// and ToProto converters from portable protobuf messages. Wire types still come
// from protocolbuffers/go; Protovalidate runs on those messages after convert.
package main

import (
	"flag"

	"github.com/sandbox-kit/kit/tooling/internal/publicfacade"
	"google.golang.org/protobuf/compiler/protogen"
)

func main() {
	var flags flag.FlagSet
	options := publicfacade.Options{
		WireImportPath: "github.com/sandbox-kit/kit/sdks/go/contracts/kit/sandbox/v1",
		WireImportName: "sandboxv1",
		PackageName:    "sandbox",
	}
	flags.StringVar(&options.PackageName, "package", options.PackageName, "Go package name for generated façades")
	flags.StringVar(&options.WireImportPath, "wire_import", options.WireImportPath, "import path of generated wire messages")
	flags.StringVar(&options.WireImportName, "wire_name", options.WireImportName, "import name for wire messages")
	flags.StringVar(&options.Roots, "roots", "kit.sandbox.v1.Config,kit.sandbox.v1.CreateOptions", "comma-separated fully-qualified root messages")
	flags.StringVar(&options.WireKeep, "wire_keep", "kit.sandbox.v1.MetadataObject", "comma-separated messages kept as wire types on the public surface")
	flags.StringVar(&options.Lang, "lang", "go", "output language: go or ts")
	flags.StringVar(&options.TSOutFile, "ts_file", "public_facade.gen.ts", "TypeScript output file name when lang=ts")

	protogen.Options{ParamFunc: flags.Set}.Run(func(plugin *protogen.Plugin) error {
		return publicfacade.Generate(plugin, options)
	})
}

package publicfacade

import "strings"

// Options configures façade generation.
type Options struct {
	PackageName    string
	WireImportPath string
	WireImportName string
	Roots          string
	WireKeep       string
	Lang           string
	TSOutFile      string
}

func (o Options) rootSet() map[string]struct{} {
	return splitSet(o.Roots)
}

func (o Options) wireKeepSet() map[string]struct{} {
	return splitSet(o.WireKeep)
}

func splitSet(csv string) map[string]struct{} {
	out := make(map[string]struct{})
	for _, part := range strings.Split(csv, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		out[part] = struct{}{}
	}
	return out
}

package publicfacade

import (
	"strings"

	"google.golang.org/protobuf/compiler/protogen"
)

// publicFieldName maps protogen field Go names onto the public SDK surface.
// Request façades use API/OAuth initialisms for a few auth fields; other names
// follow protobuf Go naming (Id, Url, TcpPort, CpuCores).
func publicFieldName(field *protogen.Field) string {
	name := field.GoName
	switch name {
	case "ApiKey":
		return "APIKey"
	case "OauthRefresh":
		return "OAuthRefresh"
	default:
		return name
	}
}

func publicMessageName(message *protogen.Message) string {
	return message.GoIdent.GoName
}

func unexported(name string) string {
	if name == "" {
		return name
	}
	// Keep leading initialism blocks lowercase as a single unit when possible.
	switch {
	case strings.HasPrefix(name, "API"):
		return "aPI" + name[3:]
	case strings.HasPrefix(name, "OAuth"):
		return "oAuth" + name[5:]
	default:
		return strings.ToLower(name[:1]) + name[1:]
	}
