package publicfacade

import (
	"fmt"
	"sort"

	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/reflect/protoreflect"
)

type model struct {
	options   Options
	roots     []*protogen.Message
	messages  []*protogen.Message
	wireKeep  map[protoreflect.FullName]bool
	byFull    map[protoreflect.FullName]*protogen.Message
	generated map[protoreflect.FullName]bool
}

func collect(plugin *protogen.Plugin, options Options) (*model, error) {
	m := &model{
		options:   options,
		wireKeep:  make(map[protoreflect.FullName]bool),
		byFull:    make(map[protoreflect.FullName]*protogen.Message),
		generated: make(map[protoreflect.FullName]bool),
	}
	for name := range options.wireKeepSet() {
		m.wireKeep[protoreflect.FullName(name)] = true
	}
	for _, file := range plugin.Files {
		for _, message := range file.Messages {
			indexMessage(m, message)
		}
	}
	for name := range options.rootSet() {
		message := m.byFull[protoreflect.FullName(name)]
		if message == nil {
			return nil, fmt.Errorf("publicfacade: unknown root message %q", name)
		}
		m.roots = append(m.roots, message)
	}
	sort.Slice(m.roots, func(i, j int) bool {
		return m.roots[i].Desc.FullName() < m.roots[j].Desc.FullName()
	})
	seen := make(map[protoreflect.FullName]bool)
	var walk func(*protogen.Message)
	walk = func(message *protogen.Message) {
		full := message.Desc.FullName()
		if seen[full] {
			return
		}
		seen[full] = true
		if m.wireKeep[full] || isWellKnown(message) {
			return
		}
		m.generated[full] = true
		m.messages = append(m.messages, message)
		for _, field := range message.Fields {
			if field.Message == nil || field.Desc.IsMap() {
				if field.Desc.IsMap() {
					if value := field.Message.Fields[1]; value.Message != nil {
						walk(value.Message)
					}
				}
				continue
			}
			walk(field.Message)
		}
	}
	for _, root := range m.roots {
		walk(root)
	}
	sort.Slice(m.messages, func(i, j int) bool {
		return m.messages[i].Desc.FullName() < m.messages[j].Desc.FullName()
	})
	return m, nil
}

func indexMessage(m *model, message *protogen.Message) {
	m.byFull[message.Desc.FullName()] = message
	for _, nested := range message.Messages {
		// Skip map-entry synthetic messages; still index real nested types.
		if nested.Desc.IsMapEntry() {
			continue
		}
		indexMessage(m, nested)
	}
}

func isWellKnown(message *protogen.Message) bool {
	switch message.Desc.FullName() {
	case "google.protobuf.Duration", "google.protobuf.Timestamp", "google.protobuf.Any",
		"google.protobuf.Struct", "google.protobuf.Value", "google.protobuf.ListValue",
		"google.protobuf.Empty", "google.protobuf.BoolValue", "google.protobuf.StringValue",
		"google.protobuf.BytesValue", "google.protobuf.Int32Value", "google.protobuf.Int64Value",
		"google.protobuf.UInt32Value", "google.protobuf.UInt64Value", "google.protobuf.FloatValue",
		"google.protobuf.DoubleValue", "google.protobuf.FieldMask":
		return true
	default:
		return false
	}
}

