// Generate emits public façades for the configured language.
func Generate(plugin *protogen.Plugin, options Options) error {
	model, err := collect(plugin, options)
	if err != nil {
		return err
	}
	switch strings.ToLower(options.Lang) {
	case "go", "":
		return emitGo(plugin, model)
