func emitGo(plugin *protogen.Plugin, m *model) error {
	// Emit once for the whole module (roots span client.proto + sandbox.proto).
	g := plugin.NewGeneratedFile("public_facade.gen.go", protogen.GoImportPath("github.com/sandbox-kit/kit/sdks/go/sandbox"))
	g.P("// Code generated by protoc-gen-kit-public. DO NOT EDIT.")
	g.P()
	g.P("package ", m.options.PackageName)
	g.P()
	g.P("import (")
	g.P(strconv.Quote(m.options.WireImportName), " ", strconv.Quote(m.options.WireImportPath))
	needsDuration := false
	for _, message := range m.messages {
		for _, field := range message.Fields {
			if field.Message != nil && field.Message.Desc.FullName() == "google.protobuf.Duration" {
				needsDuration = true
			}
		}
	}
	if needsDuration {
		g.P(`durationpb "google.golang.org/protobuf/types/known/durationpb"`)
	}
	g.P(")")
	g.P()
	g.P("// Public request/config façades mirror portable protobuf messages without")
	g.P("// wire oneof wrappers. NewClient / Create convert with ToProto* before")
	g.P("// Protovalidate and provider calls.")
	g.P()

	for _, message := range m.messages {
		emitGoStruct(g, m, message)
		g.P()
	}

	for _, root := range m.roots {
		name := publicMessageName(root)
		g.P("// ToProto", name, " converts the public façade into the wire message.")
		g.P("func ToProto", name, "(value *", name, ") *", m.options.WireImportName, ".", name, " {")
		g.P("return ", toProtoFuncName(root), "(value)")
		g.P("}")
		g.P()
	}

	for _, message := range m.messages {
		emitGoConvert(g, m, message)
		g.P()
	}
	return nil
}

func emitGoStruct(g *protogen.GeneratedFile, m *model, message *protogen.Message) {
	name := publicMessageName(message)
	if comment := message.Comments.Leading.String(); comment != "" {
		g.P("// ", name, " is the public façade for ", message.Desc.FullName(), ".")
	} else {
		g.P("// ", name, " is the public façade for ", message.Desc.FullName(), ".")
	}
	if len(message.Oneofs) > 0 {
		g.P("// Oneof fields are exclusive nested pointers; set at most one alternative.")
	}
	g.P("type ", name, " struct {")
	seenOneof := make(map[*protogen.Oneof]bool)
	for _, field := range message.Fields {
		if field.Oneof != nil && !field.Oneof.Desc.IsSynthetic() {
			if seenOneof[field.Oneof] {
				continue
			}
			seenOneof[field.Oneof] = true
			for _, oneofField := range field.Oneof.Fields {
				emitGoField(g, m, oneofField)
			}
			continue
		}
		emitGoField(g, m, field)
	}
	g.P("}")
}

func emitGoField(g *protogen.GeneratedFile, m *model, field *protogen.Field) {
	fieldName := publicFieldName(field)
	goType, err := goFieldType(m, field)
	if err != nil {
		g.P("// ERROR: ", err.Error())
		return
	}
	g.P(fieldName, " ", goType)
}

func goFieldType(m *model, field *protogen.Field) (string, error) {
	switch {
	case field.Desc.IsMap():
		key := field.Desc.MapKey()
		val := field.Desc.MapValue()
		keyType, err := scalarGoType(key.Kind())
		if err != nil {
			return "", err
		}
		valType, err := mapValueGoType(m, field, val)
		if err != nil {
			return "", err
		}
		return "map[" + keyType + "]" + valType, nil
	case field.Desc.IsList():
		elem, err := goElemType(m, field, true)
		if err != nil {
			return "", err
		}
		return "[]" + elem, nil
	default:
		return goElemType(m, field, false)
	}
}

func mapValueGoType(m *model, field *protogen.Field, val protoreflect.FieldDescriptor) (string, error) {
	switch val.Kind() {
	case protoreflect.MessageKind:
		message := field.Message.Fields[1].Message
		return goMessageType(m, message, false)
	case protoreflect.EnumKind:
		return field.Message.Fields[1].Enum.GoIdent.GoName, nil
	default:
		return scalarGoType(val.Kind())
	}
}

func goElemType(m *model, field *protogen.Field, listElem bool) (string, error) {
	switch field.Desc.Kind() {
	case protoreflect.MessageKind:
		pointer := !listElem
		return goMessageType(m, field.Message, pointer)
	case protoreflect.EnumKind:
		return field.Enum.GoIdent.GoName, nil
	default:
		base, err := scalarGoType(field.Desc.Kind())
		if err != nil {
			return "", err
		}
		if field.Desc.HasPresence() && !listElem {
			return "*" + base, nil
		}
		return base, nil
	}
}

func goMessageType(m *model, message *protogen.Message, pointer bool) (string, error) {
	var typ string
	switch {
	case message.Desc.FullName() == "google.protobuf.Duration":
		typ = "*durationpb.Duration"
		pointer = false
	case message.Desc.FullName() == "google.protobuf.Timestamp":
		typ = "*timestamppb.Timestamp"
		pointer = false
	case m.wireKeep[message.Desc.FullName()]:
		typ = message.GoIdent.GoName
	case m.generated[message.Desc.FullName()]:
		typ = publicMessageName(message)
	default:
		return "", fmt.Errorf("no public type for %s", message.Desc.FullName())
	}
	if pointer {
		return "*" + typ, nil
	}
	return typ, nil
}

func scalarGoType(kind protoreflect.Kind) (string, error) {
	switch kind {
	case protoreflect.BoolKind:
		return "bool", nil
	case protoreflect.Int32Kind, protoreflect.Sint32Kind, protoreflect.Sfixed32Kind:
		return "int32", nil
	case protoreflect.Int64Kind, protoreflect.Sint64Kind, protoreflect.Sfixed64Kind:
		return "int64", nil
	case protoreflect.Uint32Kind, protoreflect.Fixed32Kind:
		return "uint32", nil
	case protoreflect.Uint64Kind, protoreflect.Fixed64Kind:
		return "uint64", nil
	case protoreflect.FloatKind:
		return "float32", nil
	case protoreflect.DoubleKind:
		return "float64", nil
	case protoreflect.StringKind:
		return "string", nil
	case protoreflect.BytesKind:
		return "[]byte", nil
	default:
		return "", fmt.Errorf("unsupported scalar kind %v", kind)
	}
}

func emitGoConvert(g *protogen.GeneratedFile, m *model, message *protogen.Message) {
	name := publicMessageName(message)
	fn := toProtoFuncName(message)
	wire := m.options.WireImportName
	g.P("func ", fn, "(value *", name, ") *", wire, ".", name, " {")
	g.P("if value == nil {")
	g.P("return nil")
	g.P("}")
	g.P("out := &", wire, ".", name, "{}")

	seenOneof := make(map[*protogen.Oneof]bool)
	for _, field := range message.Fields {
		if field.Oneof != nil && !field.Oneof.Desc.IsSynthetic() {
			if seenOneof[field.Oneof] {
				continue
			}
			seenOneof[field.Oneof] = true
			emitGoOneofAssign(g, m, message, field.Oneof)
			continue
		}
		emitGoFieldAssign(g, m, field)
	}
	g.P("return out")
	g.P("}")
}

func emitGoOneofAssign(g *protogen.GeneratedFile, m *model, message *protogen.Message, oneof *protogen.Oneof) {
	wire := m.options.WireImportName
	msgName := publicMessageName(message)
	g.P("switch {")
	for _, field := range oneof.Fields {
		pub := publicFieldName(field)
		wrapper := msgName + "_" + field.GoName
		g.P("case value.", pub, " != nil:")
		if field.Desc.Kind() == protoreflect.MessageKind {
			conv := toProtoFuncName(field.Message)
			if m.wireKeep[field.Message.Desc.FullName()] {
				g.P("out.", oneofWireField(oneof), " = &", wire, ".", wrapper, "{", field.GoName, ": value.", pub, "}")
			} else if isWellKnown(field.Message) {
				g.P("out.", oneofWireField(oneof), " = &", wire, ".", wrapper, "{", field.GoName, ": value.", pub, "}")
			} else {
				g.P("out.", oneofWireField(oneof), " = &", wire, ".", wrapper, "{", field.GoName, ": ", conv, "(value.", pub, ")}")
			}
		} else {
			// Scalar oneof: public field is *T; wire wrapper holds T.
			g.P("out.", oneofWireField(oneof), " = &", wire, ".", wrapper, "{", field.GoName, ": *value.", pub, "}")
		}
	}
	g.P("}")
}

func oneofWireField(oneof *protogen.Oneof) string {
	return oneof.GoName
}

func emitGoFieldAssign(g *protogen.GeneratedFile, m *model, field *protogen.Field) {
	pub := publicFieldName(field)
	wireField := field.GoName
	switch {
	case field.Desc.IsMap():
		g.P("out.", wireField, " = value.", pub)
	case field.Desc.IsList() && field.Desc.Kind() == protoreflect.MessageKind && !m.wireKeep[field.Message.Desc.FullName()] && !isWellKnown(field.Message):
		conv := toProtoFuncName(field.Message)
		g.P("if value.", pub, " != nil {")
		g.P("out.", wireField, " = make([]*", m.options.WireImportName, ".", publicMessageName(field.Message), ", len(value.", pub, "))")
		g.P("for i, item := range value.", pub, " {")
		g.P("out.", wireField, "[i] = ", conv, "(item)")
		g.P("}")
		g.P("}")
	case field.Desc.Kind() == protoreflect.MessageKind && !m.wireKeep[field.Message.Desc.FullName()] && !isWellKnown(field.Message):
		g.P("out.", wireField, " = ", toProtoFuncName(field.Message), "(value.", pub, ")")
	default:
		g.P("out.", wireField, " = value.", pub)
	}
}

