  T extends
    | StartOptions
    | StopOptions
    | PauseOptions
    | ArchiveOptions
    | DeleteOptions,
>(
  operation: string,
  method:
    | ((
        id: string,
        request: T,
        options: OperationOptions,
      ) => Promise<SandboxInfo>)
    | undefined,
  request: T,
  options: OperationOptions,
): Promise<SandboxInfo> {
  return this.#serialized(
    operation,
    options,
    optionalTimeoutMs(request.timeout) ?? this.#timeoutMs,
    async (signal) => {
      if (!method) unsupported(this.providerName, operation);
      const info = await awaitWithSignal(
        () =>
          method.call(
            this.#backend,
            this.id,
            clone(request),
            operationOptions(options, signal),
          ),
        signal,
      );
      this.#info = clone({ ...info, provider: this.providerName });
      return this.info();
    },
  );
}

